-- 02. Service users, one per tool, with key-pair sign-in only.
--
-- Do not edit this file with real keys. Copy it into a Snowsight worksheet,
-- replace each placeholder there with the matching public key (the text
-- between the BEGIN and END lines, joined into one line), and run it.
-- A placeholder that is not replaced makes the statement fail, which is
-- intended. Public keys are not secret, but they are kept out of the
-- repository so each environment uses its own.
--
-- TYPE = SERVICE users cannot have a password and cannot sign in to Snowsight,
-- so a leaked username alone is useless.

use role useradmin;

create user if not exists loader_svc
    type = service
    rsa_public_key = '<LOADER_PUBLIC_KEY>'
    default_role = loader
    default_warehouse = loading_wh
    default_namespace = raw.ga4
    comment = 'Loads extracted Parquet files into RAW.';

create user if not exists dbt_svc
    type = service
    rsa_public_key = '<DBT_PUBLIC_KEY>'
    default_role = transformer
    default_warehouse = transforming_wh
    default_namespace = analytics
    comment = 'Runs dbt.';

-- The BI user is created without a key. Its sign-in method is set in the
-- Metabase milestone, once the driver's key-pair support is confirmed.
create user if not exists bi_svc
    type = service
    default_role = reporter
    default_warehouse = reporting_wh
    default_namespace = analytics.marts
    comment = 'Read-only access for Metabase and Power BI.';

use role securityadmin;

grant role loader to user loader_svc;
grant role transformer to user dbt_svc;
grant role reporter to user bi_svc;
